<?php namespace App\Actions; use App\Models\FoodItem; use App\Models\Stall; class SaveFoodItemAction { public function execute(Stall $stall, array $data, ?FoodItem $foodItem = null): FoodItem { $payload = ['stall_id' => $stall->id, 'category_id' => $data['category_id'], 'name' => strip_tags($data['name']), 'description' => isset($data['description']) ? strip_tags($data['description']) : null, 'price' => $data['price'], 'availability' => (bool) ($data['availability'] ?? true)]; if ($foodItem) { $foodItem->update($payload); return $foodItem; } return FoodItem::create($payload); } }